using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageRequirementTests
{
    private const string AttributeName = "System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverageAttribute";

    private const string Source = """
using MessagePack;

namespace Receipts.Sample
{
    [GeneratedMessagePackResolver]
    partial class MyResolver { }

    public enum Color { Red, Green }

    [MessagePackObject]
    public class IntKeyed
    {
        [Key(0)]
        public int Value { get; set; }

        [Key(1)]
        public Color Color { get; set; }
    }

    [MessagePackObject]
    public class StringKeyed
    {
        [Key("name")]
        public string Name { get; set; }
    }

    [Union(0, typeof(UnionCase))]
    public interface IShape { }

    [MessagePackObject]
    public class UnionCase : IShape
    {
        [Key(0)]
        public int Sides { get; set; }
    }
}
""";

    [Fact]
    public async Task GeneratedFormatters_AreExcludedFromCodeCoverage()
    {
        (Compilation output, List<SyntaxTree> generated) = await RunGeneratorAsync();
        Assert.NotEmpty(generated);

        var formatters = new List<INamedTypeSymbol>();
        foreach (SyntaxTree tree in generated)
        {
            SemanticModel model = output.GetSemanticModel(tree);
            foreach (ClassDeclarationSyntax cls in tree.GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>())
            {
                if (model.GetDeclaredSymbol(cls) is INamedTypeSymbol symbol && symbol.AllInterfaces.Any(i => i.Name == "IMessagePackFormatter" && i.IsGenericType))
                {
                    formatters.Add(symbol);
                }
            }
        }

        Assert.NotEmpty(formatters);
        foreach (INamedTypeSymbol formatter in formatters)
        {
            Assert.True(HasExcludeAttribute(formatter), $"Generated formatter {formatter.ToDisplayString()} is not decorated with ExcludeFromCodeCoverage.");
        }
    }

    [Fact]
    public async Task GeneratedResolver_IsExcludedFromCodeCoverage()
    {
        (Compilation output, List<SyntaxTree> _) = await RunGeneratorAsync();
        INamedTypeSymbol? resolver = output.GetTypeByMetadataName("Receipts.Sample.MyResolver");
        Assert.NotNull(resolver);
        Assert.True(HasExcludeAttribute(resolver!), "Generated resolver is not decorated with ExcludeFromCodeCoverage.");
    }

    private static bool HasExcludeAttribute(INamedTypeSymbol symbol)
        => symbol.GetAttributes().Any(a => a.AttributeClass?.ToDisplayString() == AttributeName);

    private static async Task<(Compilation Output, List<SyntaxTree> Generated)> RunGeneratorAsync()
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        var framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> references = framework.Concat<MetadataReference>(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToList();
        SyntaxTree original = CSharpSyntaxTree.ParseText(Source, parseOptions);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsCoverageAssembly",
            new[] { original },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out _);
        List<SyntaxTree> generated = output.SyntaxTrees.Where(t => !ReferenceEquals(t, original)).ToList();
        return (output, generated);
    }
}

