using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageLegacyTargetTests
{
    private const string AttributeName = "System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverageAttribute";

    private const string Source = """
using MessagePack;

namespace Receipts.Legacy
{
    [GeneratedMessagePackResolver]
    partial class LegacyResolver { }

    [MessagePackObject]
    public class LegacyObject
    {
        [Key(0)]
        public int Value { get; set; }
    }
}
""";

    // ExcludeFromCodeCoverageAttribute exists on netstandard2.0 and .NET Framework 4.0+,
    // so the requirement (all generated code decorated) applies to those targets too.
    [Theory]
    [InlineData("NETSTANDARD2_0")]
    [InlineData("NETFRAMEWORK")]
    public async Task GeneratedCode_IsExcludedFromCodeCoverage_OnLegacyTargets(string symbol)
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest, preprocessorSymbols: new[] { symbol });
        var framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> references = framework.Concat<MetadataReference>(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToList();
        SyntaxTree original = CSharpSyntaxTree.ParseText(Source, parseOptions);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsLegacyAssembly",
            new[] { original },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out _);

        var formatters = new List<INamedTypeSymbol>();
        foreach (SyntaxTree tree in output.SyntaxTrees.Where(t => !ReferenceEquals(t, original)))
        {
            SemanticModel model = output.GetSemanticModel(tree);
            foreach (ClassDeclarationSyntax cls in tree.GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>())
            {
                if (model.GetDeclaredSymbol(cls) is INamedTypeSymbol s && s.AllInterfaces.Any(i => i.Name == "IMessagePackFormatter" && i.IsGenericType))
                {
                    formatters.Add(s);
                }
            }
        }

        Assert.NotEmpty(formatters);
        foreach (INamedTypeSymbol formatter in formatters)
        {
            Assert.True(
                formatter.GetAttributes().Any(a => a.AttributeClass?.ToDisplayString() == AttributeName),
                $"With {symbol} defined, generated formatter {formatter.ToDisplayString()} is not decorated with ExcludeFromCodeCoverage.");
        }

        INamedTypeSymbol? resolver = output.GetTypeByMetadataName("Receipts.Legacy.LegacyResolver");
        Assert.NotNull(resolver);
        Assert.True(
            resolver!.GetAttributes().Any(a => a.AttributeClass?.ToDisplayString() == AttributeName),
            $"With {symbol} defined, the generated resolver is not decorated with ExcludeFromCodeCoverage.");
    }
}
